self.KB_CONTENT["card:793360"]={"id":"card:793360","ty":"card","sourceId":"793360","title":"『每月製令變更狀況維護作業』中的『材料型態 (TI011)』為何？","ver":"GP4以上","topic":"製令","keywords":["製令","客戶","廠商","材料"],"y":"other","answer":"* 分為1.直接材料、2.間接材料、3.廠商供料、4.不發料及5.客戶供料。* 此欄位僅作顯示。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
