self.KB_CONTENT["card:779470"]={"id":"card:779470","ty":"card","sourceId":"779470","title":"『委外進貨單建立作業(IDL)』中的『營業稅率 (TH030)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","營業稅","大於"],"y":"other","answer":"* 預設「共用參數設定」之營業稅率。* 顯示與輸入時以5.00%顯示，但存入時將資料除以100存入0.0500。* 此欄位必須大於等於零。其他資料","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
